import { userSchemaValidation } from "../Validations/UserValidations";
import { useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import { useState } from "react";
import { Button, Col, Label, Container, Row, Form } from "reactstrap";
import "../Styles/UserRegister.css";

const MAJORS = [
  "",
  "Information Technology",
  "Business Administration",
  "Engineering",
  "Mass Communication",
];

const UserRegister = () => {
  // 🔹 State variables
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [major, setMajor] = useState("");
  const [age, setAge] = useState("");

  // 🔹 React Hook Form setup with Yup validation
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm({
    resolver: yupResolver(userSchemaValidation),
  });

  // 🔹 Handle form submission
  const onSubmit = (data) => {
    console.log("Form Data:", data);
    alert("Student Registered ✅");
    localStorage.setItem("userData", JSON.stringify(data));
  };

  return (
    <Container className="div-form">
      {/* Title and subtitle */}
      <h1>
        Create your <span>account</span>
      </h1>
      <p className="sub-text">Please fill in your details to continue</p>

      {/* Registration form */}
      <Form onSubmit={handleSubmit(onSubmit)}>
        {/* Full Name */}
        <Row>
          <Col md={12}>
            <Label>Full Name</Label>
            <input
              type="text"
              name="fullName"
              placeholder="Your name"
              {...register("fullName", {
                value: fullName,
                onChange: (e) => setFullName(e.target.value),
              })}
            />
            <p className="error">{errors.fullName?.message}</p>
          </Col>
        </Row>

        {/* Email */}
        <Row>
          <Col md={12}>
            <Label>Email</Label>
            <input
              type="email"
              name="email"
              placeholder="you@example.com"
              {...register("email", {
                value: email,
                onChange: (e) => setEmail(e.target.value),
              })}
            />
            <p className="error">{errors.email?.message}</p>
          </Col>
        </Row>

        {/* Password */}
        <Row>
          <Col md={12}>
            <Label>Password</Label>
            <input
              type="password"
              name="password"
              placeholder="********"
              {...register("password", {
                value: password,
                onChange: (e) => setPassword(e.target.value),
              })}
            />
            <p className="error">{errors.password?.message}</p>
          </Col>
        </Row>

        {/* Major */}
        <Row>
          <Col md={12}>
            <Label>Major</Label>
            <select
              {...register("major", {
                value: major,
                onChange: (e) => setMajor(e.target.value),
              })}
            >
              {MAJORS.map((m, i) => (
                <option key={i} value={m}>
                  {m === "" ? "Select your major" : m}
                </option>
              ))}
            </select>
            <p className="error">{errors.major?.message}</p>
          </Col>
        </Row>

        {/* Age */}
        <Row>
          <Col md={12}>
            <Label>Age</Label>
            <input
              type="number"
              name="age"
              min="17"
              max="45"
              {...register("age", {
                value: age,
                onChange: (e) => setAge(e.target.value),
              })}
            />
            <p className="error">{errors.age?.message}</p>
          </Col>
        </Row>

        {/* Submit button */}
        <Row>
          <Col md={12}>
            <Button color="success">Sign Up</Button>
          </Col>
        </Row>
      </Form>
    </Container>
  );
};

export default UserRegister;
